class Pool {
  constructor(size){ this.free = []; for(let i=0;i<size;i++) this.free.push({id:i}); }
  acquire(){ if(this.free.length===0) throw new Error('pool exhausted'); return this.free.pop(); }
  release(c){ this.free.push(c); }
  // BUG: returns the connection only when work() succeeds; a throw leaks the slot.
  withConnection(work){
    const conn = this.acquire();
    const result = work(conn);
    this.release(conn);
    return result;
  }
}

